// Parse the storyboard JSON
const text = $json.content.parts[0].text;
let clean = text.trim().replace(/^```json\s*/i,'').replace(/^```\s*/,'').replace(/```$/,'').trim();
let d;
try { d = JSON.parse(clean); } catch (e) { throw new Error('Storyboard model returned invalid JSON. Raw: ' + clean); }
if (!Array.isArray(d.scenes) || d.scenes.length < 2) throw new Error('Storyboard needs at least 2 scenes.');
const full_narration = (d.scenes || []).map(s => String(s.narration || '').trim()).filter(Boolean).join(' ');
return [{ json: { ...d, full_narration } }];

// Fan out one item per scene; inject the SAME cast + style into every image prompt for consistency
const d = $('Parse Storyboard').first().json;
const style = d.style_guide || '';
const adult = (d.cast && d.cast.adult) || '';
const child = (d.cast && d.cast.child) || '';
const cap = Number($('Config').first().json.maxScenes) || 40;
const scenes = (Array.isArray(d.scenes) ? d.scenes : []).slice(0, cap);
return scenes.map((s, i) => ({
  json: {
    scene_index: i + 1,
    total: scenes.length,
    beat: s.beat || '',
    narration: s.narration || '',
    on_screen_text: s.on_screen_text || '',
    duration: Math.max(2, Math.min(4, (String(s.narration || '').trim().split(' ').filter(Boolean).length || 7) / 2.5)),
    image_prompt: 'A SINGLE full-frame illustration showing ONE moment only. This is ONE picture — NOT a comic strip, NOT multiple panels, NOT a grid, NO split frames or boxes. STRICTLY BLACK AND WHITE — monochrome grayscale ONLY: black ink outlines with light grey flat shading on a plain white background. Absolutely NO color anywhere; ignore any colors mentioned in the descriptions and render everything in black, white and grey. Simple clean cartoon line-art, friendly and expressive, vertical 9:16 portrait. CHARACTERS (keep EXACTLY identical, same simple character design in every image): ' + adult + ' ; ' + child +
      '. Depict ONLY this single moment, filling the whole frame: ' + (s.image_action || '') +
      '. Strong clear emotion, simple uncluttered background, a little empty space near the top or bottom for captions.' +
      ' Do NOT divide the image into panels, frames, or boxes. Do NOT render any text, words, letters, numbers, logos, or watermarks.'
  }
}));

// Validate each Gemini image; REGENERATE any corrupt (0-byte) one in place (up to 3 tries) so every scene survives and stays matched to the voiceover. If a scene truly can't be recovered it is skipped (graceful fallback).
const all = $input.all();
const meta = $('Split Scenes').all();
const MAX = 3;
const out = [];
let regenCount = 0, dropCount = 0;
for (let i = 0; i < all.length; i++) {
  const m = (meta[i] && meta[i].json) ? meta[i].json : {};
  let bin = (all[i].binary && all[i].binary.data) ? all[i].binary.data : null;
  let size = 0;
  if (bin) { const buf = await this.helpers.getBinaryDataBuffer(i, 'data'); size = buf ? buf.length : 0; }
  let attempts = 0;
  while (size <= 1024 && attempts < MAX && m.image_prompt) {
    attempts++;
    try {
      const resp = await this.helpers.httpRequestWithAuthentication('googlePalmApi', {
        method: 'POST',
        url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-image:generateContent',
        body: { contents: [{ parts: [{ text: m.image_prompt }] }] },
        json: true
      });
      const parts = (resp && resp.candidates && resp.candidates[0] && resp.candidates[0].content && resp.candidates[0].content.parts) || [];
      const imgPart = parts.find(p => p.inlineData && p.inlineData.data);
      if (imgPart) {
        const buf = Buffer.from(imgPart.inlineData.data, 'base64');
        if (buf && buf.length > 1024) {
          bin = await this.helpers.prepareBinaryData(buf, 'image.png', imgPart.inlineData.mimeType || 'image/png');
          size = buf.length;
        }
      }
    } catch (e) { /* try again */ }
  }
  if (attempts > 0 && size > 1024) regenCount++;
  if (size > 1024 && bin) {
    out.push({ json: { scene_index: m.scene_index, regenerated: attempts > 0 }, binary: { data: bin } });
  } else {
    dropCount++;
  }
}
if (out.length < 2) throw new Error('Only ' + out.length + ' valid image(s) after regeneration; ' + dropCount + ' unrecoverable.');
return out;

// Aggregate all scene image URLs + durations into a JSON2Video movie spec
const items = $input.all();
const meta = $('Split Scenes').all();
const scenes = [];
for (let i = 0; i < items.length; i++) {
  const imgs = items[i].json.images;
  const url = imgs && imgs[0] ? imgs[0].source : null;
  if (!url) continue;
  const dur = (meta[i] && meta[i].json.duration) ? meta[i].json.duration : 3;
  scenes.push({ elements: [ { type: 'image', src: url, duration: dur, zoom: 2 } ] });
}
if (scenes.length < 2) throw new Error('Need at least 2 scene images to assemble a video.');
return [{ json: { movie: { resolution: 'custom', width: 1080, height: 1920, scenes } } }];

