// Gemini TTS returns raw PCM audio (base64). Wrap it in a WAV header to make a playable file.
const part = $json.candidates[0].content.parts[0];
const b64 = part.inlineData.data;
const mt = part.inlineData.mimeType || '';
const m = mt.match(/rate=(\d+)/);
const sampleRate = m ? parseInt(m[1], 10) : 24000;
const channels = 1, bits = 16;
const pcm = Buffer.from(b64, 'base64');
const byteRate = sampleRate * channels * bits / 8;
const blockAlign = channels * bits / 8;
const h = Buffer.alloc(44);
h.write('RIFF', 0); h.writeUInt32LE(36 + pcm.length, 4); h.write('WAVE', 8);
h.write('fmt ', 12); h.writeUInt32LE(16, 16); h.writeUInt16LE(1, 20); h.writeUInt16LE(channels, 22);
h.writeUInt32LE(sampleRate, 24); h.writeUInt32LE(byteRate, 28); h.writeUInt16LE(blockAlign, 32); h.writeUInt16LE(bits, 34);
h.write('data', 36); h.writeUInt32LE(pcm.length, 40);
const wav = Buffer.concat([h, pcm]);
const bin = await this.helpers.prepareBinaryData(wav, 'voiceover.wav', 'audio/wav');
return [{ json: { ok: true, bytes: wav.length, seconds: Math.round(pcm.length / byteRate) }, binary: { data: bin } }];

